package com.example.inventory.controller;
import com.example.inventory.model.*;import com.example.inventory.server.HttpUtil;import com.example.inventory.service.OrderService;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpExchange;import java.io.IOException;import java.math.BigDecimal;import java.sql.Date;import java.util.*;
public final class OrderController {
 private final OrderService service;private final ObjectMapper mapper;private final String prefix,kind;
 public OrderController(OrderService s,ObjectMapper m,String p,String k){service=s;mapper=m;prefix=p;kind=k;}
 public void handle(HttpExchange e)throws IOException{try{String method=e.getRequestMethod().toUpperCase();String path=e.getRequestURI().getPath();Integer id=parse(path);if("OPTIONS".equals(method)){HttpUtil.sendEmpty(e,204);return;}if("GET".equals(method)){get(e,id);return;}if("POST".equals(method)){if(id==null)create(e);else action(e,id,path);return;}HttpUtil.sendError(e,405,"METHOD_NOT_ALLOWED","Method is not supported.");}catch(OrderService.ValidationException x){HttpUtil.sendError(e,400,"VALIDATION_ERROR",x.getMessage());}catch(IllegalStateException x){HttpUtil.sendError(e,409,"INVALID_STATE",x.getMessage());}catch(NoSuchElementException x){HttpUtil.sendError(e,404,"NOT_FOUND","Order was not found.");}catch(java.sql.SQLException x){if(x.getErrorCode()==1452)HttpUtil.sendError(e,400,"INVALID_REFERENCE","A referenced record does not exist.");else HttpUtil.sendError(e,500,"DATABASE_ERROR","The order operation could not be completed.");}catch(Exception x){HttpUtil.sendError(e,400,"INVALID_REQUEST","Request JSON is invalid.");}}
 private void get(HttpExchange e,Integer id)throws IOException,java.sql.SQLException{if("stock".equals(kind)){HttpUtil.sendJson(e,200,service.transactions());return;}if(id==null)HttpUtil.sendJson(e,200,"purchase".equals(kind)?service.purchases():service.sales());else{Object x="purchase".equals(kind)?service.purchase(id).orElse(null):service.sale(id).orElse(null);if(x==null)HttpUtil.sendError(e,404,"NOT_FOUND","Order was not found.");else HttpUtil.sendJson(e,200,x);}}
 private void create(HttpExchange e)throws IOException,java.sql.SQLException{JsonNode n=mapper.readTree(HttpUtil.readBody(e));String date=text(n,"orderDate");if("purchase".equals(kind)){List<PurchaseOrder.Detail>d=new ArrayList<>();for(JsonNode x:array(n,"details"))d.add(new PurchaseOrder.Detail(0,intv(x,"productId"),intv(x,"quantity"),decimal(x,"unitPrice")));HttpUtil.sendJson(e,201,service.createPurchase(intv(n,"supplierId"),Date.valueOf(date),nullableInt(n,"approvedByManagerId"),d));}else{List<SalesOrder.Detail>d=new ArrayList<>();for(JsonNode x:array(n,"details"))d.add(new SalesOrder.Detail(0,intv(x,"productId"),intv(x,"quantity"),decimal(x,"unitPrice")));HttpUtil.sendJson(e,201,service.createSale(intv(n,"customerId"),Date.valueOf(date),d));}}
 private void action(HttpExchange e,int id,String path)throws IOException,java.sql.SQLException{
  if("stock".equals(kind)){HttpUtil.sendError(e,405,"METHOD_NOT_ALLOWED","Stock transactions do not support actions.");return;}
  boolean cancel=path.endsWith("/cancel");
  if("purchase".equals(kind)&&!cancel&&!path.endsWith("/receive")){HttpUtil.sendError(e,405,"METHOD_NOT_ALLOWED","Use /receive or /cancel.");return;}
  if("sale".equals(kind)&&!cancel&&!path.endsWith("/complete")){HttpUtil.sendError(e,405,"METHOD_NOT_ALLOWED","Use /complete or /cancel.");return;}
  JsonNode n=mapper.readTree(HttpUtil.readBody(e));Integer employee=nullableInt(n,"recordedByEmployeeId");
  if("purchase".equals(kind)){if(cancel)service.cancelPurchase(id);else service.receive(id,employee);HttpUtil.sendJson(e,200,service.purchase(id).orElseThrow());}
  else{if(cancel)service.cancelSale(id);else service.complete(id,employee);HttpUtil.sendJson(e,200,service.sale(id).orElseThrow());}
 }
 private Integer parse(String p){if(p.equals(prefix)||p.equals(prefix+"/"))return null;String tail=p.substring(prefix.length());for(String suffix:new String[]{"/receive","/complete","/cancel"})if(tail.endsWith(suffix)){tail=tail.substring(0,tail.length()-suffix.length());break;}try{return Integer.valueOf(tail.replace("/",""));}catch(Exception x){throw new OrderService.ValidationException("Order ID must be a number.");}}
 private String text(JsonNode n,String f){JsonNode v=n==null?null:n.get(f);if(v==null||v.isNull()||v.asText().isBlank())throw new OrderService.ValidationException(f+" is required.");return v.asText();}private int intv(JsonNode n,String f){JsonNode v=n==null?null:n.get(f);if(v==null||!v.canConvertToInt())throw new OrderService.ValidationException(f+" must be an integer.");return v.asInt();}private Integer nullableInt(JsonNode n,String f){JsonNode v=n==null?null:n.get(f);return v==null||v.isNull()?null:intv(n,f);}private BigDecimal decimal(JsonNode n,String f){try{return new BigDecimal(text(n,f));}catch(NumberFormatException x){throw new OrderService.ValidationException(f+" must be a number.");}}private JsonNode array(JsonNode n,String f){JsonNode v=n==null?null:n.get(f);if(v==null||!v.isArray()||v.isEmpty())throw new OrderService.ValidationException(f+" must contain at least one detail.");return v;}
}
